import { describe, it, expect } from 'vitest';
import { readFileSync, existsSync, readdirSync, statSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { NATIVE_URL_SCHEME, NATIVE_AUTH_CALLBACK_URL } from '@/lib/platform';

/**
 * The tracked Android and iOS projects are configuration, so they are reviewed
 * like configuration.
 *
 * `android/` and `ios/` are committed rather than regenerated by `cap add` (the
 * decision and its tradeoff are in docs/kiro/NATIVE_RELEASE_GUIDE.md). That
 * choice only pays off if the hardening in them cannot drift: `cap add` would
 * happily overwrite the manifest with a template that declares no backup rules,
 * a wide-open deep link and a debuggable WebView, and nothing in a web test
 * suite would notice.
 *
 * So this suite reads the REAL files that ship, not fixtures, and pins the
 * properties a store review and a privacy review depend on. The Android side has
 * a JVM twin in android/app/src/test/java/app/gomsinlog/NativeConfigTest.java
 * which runs under `./gradlew :app:testDebugUnitTest`; this file is what runs in
 * the plain `npm test` gate, where no Android SDK is required.
 */

const repoRoot = resolve(process.cwd());

function read(relativePath: string): string {
  return readFileSync(join(repoRoot, relativePath), 'utf8');
}

/** Value of a `<key>` in a plist whose value is a `<string>`. */
function plistString(plist: string, key: string): string | null {
  const match = plist.match(
    new RegExp(`<key>${key}</key>\\s*<string>([\\s\\S]*?)</string>`),
  );
  return match ? match[1] : null;
}

/** True when the plist declares `key` at all, whatever its value type. */
function plistHasKey(plist: string, key: string): boolean {
  return new RegExp(`<key>${key}</key>`).test(plist);
}

/**
 * The file with every XML comment removed.
 *
 * These files document what is deliberately ABSENT by naming it, so a negative
 * assertion against the raw text fails on the explanation rather than on a real
 * declaration. Absence has to be checked against the markup only.
 */
function withoutComments(xml: string): string {
  return xml.replace(/<!--[\s\S]*?-->/g, '');
}

/** Every file tracked-or-untracked under `dir`, ignoring build output. */
function walk(dir: string, skip: (path: string) => boolean): string[] {
  const out: string[] = [];
  for (const entry of readdirSync(join(repoRoot, dir))) {
    const relative = `${dir}/${entry}`;
    if (skip(relative)) continue;
    if (statSync(join(repoRoot, relative)).isDirectory()) out.push(...walk(relative, skip));
    else out.push(relative);
  }
  return out;
}

