/** 곰신로그 escaped, so a charset accident cannot make an assertion pass. */
const STORE_LABEL = '\uACF0\uC2E0\uB85C\uADF8';

describe('the deep-link scheme agrees everywhere it is registered', () => {
  it('platform.ts, capacitor.config.ts and both native projects use one literal', () => {
    expect(NATIVE_URL_SCHEME).toBe('gomsinlog');
    expect(capacitorConfig).toContain(`customUrlScheme: '${NATIVE_URL_SCHEME}'`);
    expect(manifest).toContain(`android:scheme="${NATIVE_URL_SCHEME}"`);
    expect(infoPlist).toContain(`<string>${NATIVE_URL_SCHEME}</string>`);
    // The stale Capacitor template value (the appId) is a trap: it looks like a
    // scheme and is what a regenerated manifest would reference.
    expect(strings).toContain(`<string name="custom_url_scheme">${NATIVE_URL_SCHEME}</string>`);
    expect(strings).not.toContain('<string name="custom_url_scheme">app.gomsinlog</string>');
  });

  it('the Android intent-filter pins exactly the callback route the app builds', () => {
    expect(NATIVE_AUTH_CALLBACK_URL).toBe('gomsinlog://auth/callback');
    const filter = manifest.slice(manifest.indexOf('android.intent.action.VIEW'));
    expect(filter).toContain('android:scheme="gomsinlog"');
    expect(filter).toContain('android:host="auth"');
    expect(filter).toContain('android:path="/callback"');
    // A prefix or pattern match would claim every `gomsinlog://` URL again.
    expect(manifest).not.toContain('android:pathPrefix');
    expect(manifest).not.toContain('android:pathPattern');
    expect(manifest).not.toContain('android:pathSuffix');
  });

  it('iOS registers the one scheme and nothing else', () => {
    const urlTypes = infoPlist.slice(
      infoPlist.indexOf('<key>CFBundleURLTypes</key>'),
      infoPlist.indexOf('<key>NSCameraUsageDescription</key>'),
    );
    const schemes = [...urlTypes.matchAll(/<string>([^<]+)<\/string>/g)].map((m) => m[1]);
    expect(schemes).toContain('gomsinlog');
    // Editor / owner role strings are part of the dict; the only *scheme* array
    // entry must be ours, so nothing else may look like a URL scheme.
    expect(schemes.filter((s) => !s.includes('.') && s !== 'Editor' && s !== 'Owner'))
      .toEqual(['gomsinlog']);
    // Universal Links are not used, so no associated domain may appear.
    expect(withoutComments(entitlements)).not.toContain('com.apple.developer.associated-domains');
  });
});

